"""Render BENCHMARKS.md from completed, verified release reports only."""
import json,pathlib
root=pathlib.Path(__file__).resolve().parents[1];out=root/'benchmarks/verified-gates'
rows=[]
for p in sorted(out.glob('*.json')):
 r=json.loads(p.read_text())
 if r.get('release_build') is not True or 'sizes' not in r:continue
 assert r['decoded_records']==r['records']
 if r['format']=='strata':assert r['verified_records']==r['records']
 r['file']=str(p.relative_to(root));rows.append(r)
order=['plain','manual','balanced','max_compression','max_ingest','jsonl','fixed','parquet']
rows.sort(key=lambda r:(r['tag'],r['records'],order.index(r['profile']) if r['profile'] in order else 99,r['metrics']['workers'] or 0))
env=json.loads((out/'baseline-environment.json').read_text())
lines=['# Strata measured baseline','', '**Synthetic market-v2 only. No results in this document measure the purchased Nasdaq/Databento corpus; those files have not been downloaded.**','', '## Hardware and build','',f"- {env['cpu']}; {env['logical_cpus']} logical CPUs; {env['ram_bytes']:,} RAM bytes (64 GiB).",f"- {env['platform']}; {env['rustc']}; {env['cargo']}.",f"- Baseline started {env['started_utc']}; release binary SHA-256 `{env['binary_sha256']}`.",'- No Git repository was present. Source/lockfile hashes and exact commands are saved in each run environment JSON.','', '## Methodology','', '- Release binaries only. Seed 42; generator market-v2 is deterministic across block sizes. Eight fields: timestamp, sequence, order_id, symbol, price, quantity, side, event_type. Timestamp jitter, skewed symbols/actions, variable price/quantity and mixed new/reused order IDs. This is a reproducible compression workload, not a replay of a coherent exchange order book.','- Plain stores every column with Plain + None. Manual uses the saved benchmark market profile. Automatic balanced, maximum-compression, and maximum-ingest profiles are chosen by real optimizer experiments on the first 16,384 generated rows. All candidate data is written, decoded and equality-checked. The chosen profiles are frozen across all four sizes.','- Runs execute separately and sequentially. Encode wall time starts before generation/writer setup and ends after all background workers and writers close. It includes bounded chunk generation and backpressure, and uses fast durability (OS page cache; no fsync guarantee).','- Strata uses two workers, 65,536 rows/block, and a 256 MiB soft segment target. JSONL/fixed/Parquet use a single writer; the harness worker argument does not make those writers parallel. Parquet uses Arrow/Parquet 53.4.1, Zstd level 3, default row-group settings.','- Logical bytes are exact schema-width numeric/boolean payloads and actual UTF-8/binary lengths; null payload is zero. Physical Strata bytes include segments and the dataset manifest. Benchmark provenance/profile files are outside the dataset and excluded. Ratio = logical/physical; larger is better. MB/GB are decimal; GiB is binary.','- Strata decode materializes every field in every record through bounded blocks and black_box. A separate, untimed second scan compares every decoded record to the deterministic source. Query selects 1,000 sequence values around the midpoint, checks every value, and uses actual compressed data without indexes.','- JSONL decode parses every JSON value; fixed decode materializes every typed field; Parquet decode materializes all Arrow columns and batches. These produce different in-memory representations, so their decode rates are not like-for-like engine latency claims. Each target must decode the full requested record count.','- Peak RSS, user/system CPU and total process wall time are measured by macOS /usr/bin/time -l and include verification/query as well as ingest/decode. CPU percent is relative to one core. Filesystem cache is warm; no direct I/O or cold-cache claim.','- Phase encode MB/s is logical bytes divided by accumulated worker encode time (not parallel wall throughput). Compression and I/O phase counters are in the raw canonical metrics. Baseline-format phase encode is not instrumented; their encode wall throughput is shown instead.','- One run per matrix cell; repeated runs are separate tables, not averaged or substituted. No confidence intervals. The optimizer sees a prefix sample and timing noise can alter its winner. No tuning changes were made to improve these baseline numbers.','', '## Measured results','']
for tag in sorted(set(r['tag'] for r in rows)):
 lines += [f'### {tag}','', '| Records | Format/profile | Logical bytes | Physical bytes | Ratio | Ingest records/s | Logical GB/s | Disk MB/s | Decode MB/s | Query ms | Peak RSS MiB |','|---:|:---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in rows:
  if r['tag']!=tag:continue
  m=r['metrics'];s=r['sizes'];usage=r.get('process_usage',{});rss=usage.get('peak_rss_bytes');q=m.get('query_ms')
  lines.append(f"| {r['records']:,} | [{r['profile']}]({r['file']}) | {s['logical_bytes']:,} | {s['physical_bytes']:,} | {m['compression_ratio']:.4f} | {m['records_per_sec']:,.0f} | {m['logical_gb_s']:.5f} | {m['disk_mb_s']:.2f} | {m['decode_mb_s']:.2f} | {f'{q:.2f}' if q is not None else '—'} | {f'{rss/1048576:.1f}' if rss is not None else '—'} |")
 lines += ['', '| Records | Format/profile | Encode phase MB/s | Encode wall MB/s | Decode records/s | CPU % of one core | Whole process s | Verified Strata rows |','|---:|:---|---:|---:|---:|---:|---:|---:|']
 for r in rows:
  if r['tag']!=tag:continue
  m=r['metrics'];usage=r.get('process_usage',{});cpu=usage.get('cpu_percent_of_one_core');wall=usage.get('process_wall_seconds');phase=f"{m['encode_mb_s']:.2f}" if r['format']=='strata' else '—'
  lines.append(f"| {r['records']:,} | {r['profile']} | {phase} | {r['sizes']['logical_bytes']/1e6/r['encode_wall_seconds']:.2f} | {r['records']/r['decode_wall_seconds']:,.0f} | {f'{cpu:.1f}' if cpu is not None else '—'} | {f'{wall:.2f}' if wall is not None else '—'} | {r['verified_records']:,} |")
 lines += ['']
lines += ['## Reproduction and retained evidence','', '```sh','cargo build --workspace --release','python3 scripts/run_baseline.py --prepare','python3 scripts/summarize_baseline.py','```','', 'The runner refuses existing result paths and fails on a missing/failed run. For a fresh rerun choose new `--out`, `--work`, and `--tag`. For repeats using frozen profiles, keep `--out` and omit `--prepare`; use a new tag. The script does not silently downsample any requested size.','', '- [Measured JSON, process resource logs, and frozen profiles](benchmarks/verified-gates/)','- [Run environment](benchmarks/verified-gates/baseline-environment.json)','- [Benchmark runner](scripts/run_baseline.py)','- [Streaming release harness](crates/strata-bench/src/bin/baseline.rs)','', 'Historical files elsewhere under benchmarks/ were created before this verification pass and are not evidence for the tables above. Real Nasdaq results are published separately in BENCHMARKS.md and benchmarks/nasdaq/. Synthetic results do not support real-corpus claims.']
(root/'SYNTHETIC_BENCHMARKS.md').write_text('\n'.join(lines)+'\n')
print(f'Rendered {len(rows)} actually completed runs')
